#!/bin/bash
# Reference solution: both heredocs unquoted (DOMAIN and PORT expand), every
# $ that belongs to nginx or to the generated script escaped as \$, plus an
# argument check.
cat > gen_vhost.sh <<'SCRIPT'
#!/bin/bash
# gen_vhost.sh DOMAIN PORT
# Writes sites/DOMAIN.conf (nginx vhost) and sites/DOMAIN-healthcheck.sh.
if [ $# -ne 2 ] || [[ ! $2 =~ ^[0-9]+$ ]]; then
  echo "usage: gen_vhost.sh DOMAIN PORT" >&2
  exit 2
fi
domain=$1
port=$2
mkdir -p sites

cat > "sites/$domain.conf" <<EOF
# generated by gen_vhost.sh - do not edit by hand
server {
    listen 80;
    server_name $domain;

    access_log /var/log/nginx/$domain.access.log;

    location / {
        proxy_pass http://127.0.0.1:$port;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
    }

    location ~ /\.(git|env) {
        deny all;
    }
}
EOF

cat > "sites/$domain-healthcheck.sh" <<EOF
#!/bin/bash
# healthcheck for $domain (generated by gen_vhost.sh)
# usage: $domain-healthcheck.sh [PATH]      default PATH: /healthz
path="\${1:-/healthz}"
url="http://127.0.0.1:$port\$path"
if curl -fsS -o /dev/null -H "Host: $domain" "\$url"; then
  echo "OK \$url"
else
  echo "FAIL \$url" >&2
  exit 1
fi
EOF
chmod +x "sites/$domain-healthcheck.sh"
echo "wrote sites/$domain.conf and sites/$domain-healthcheck.sh"
SCRIPT
./gen_vhost.sh shop.example.com 8081
diff examples/shop.example.com.conf sites/shop.example.com.conf &&
  diff examples/shop.example.com-healthcheck.sh sites/shop.example.com-healthcheck.sh &&
  echo "same as the examples"
